BEGIN TRANSACTION;
CREATE TABLE bounties (
        id TEXT PRIMARY KEY,
        bounty_id TEXT,
        title TEXT NOT NULL,
        platform TEXT,
        category TEXT,
        repo TEXT,
        pr_number INTEGER,
        pr_url TEXT,
        source_url TEXT,
        reward_amount REAL DEFAULT 0,
        reward_currency TEXT DEFAULT 'USDC',
        amount_usd REAL DEFAULT 0,
        status TEXT,
        payout_status TEXT,
        payout_text TEXT,
        payment_network TEXT,
        settlement_wallet TEXT,
        is_sprint INTEGER DEFAULT 0,
        is_in_review INTEGER DEFAULT 0,
        is_won INTEGER DEFAULT 0,
        is_archived INTEGER DEFAULT 0,
        is_grant INTEGER DEFAULT 0,
        expected_value REAL DEFAULT 0,
        final_score REAL DEFAULT 0,
        red_team_score REAL DEFAULT 0,
        sandbox_status TEXT,
        commit_sha TEXT,
        tx_hash TEXT,
        submitted_at TEXT,
        updated_at TEXT,
        raw_json TEXT
    );
CREATE TABLE maintainer_feedback (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        repo TEXT NOT NULL,
        pr TEXT NOT NULL,
        author TEXT NOT NULL,
        date_recorded TEXT NOT NULL,
        suggested_amount_usd REAL DEFAULT 0,
        formula_snippet TEXT,
        notes TEXT
    );
CREATE TABLE mining_telemetry (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        recorded_at TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        cluster_name TEXT,
        global_rank INTEGER,
        global_rank_title TEXT,
        active_rigs INTEGER,
        total_hashrate_mhs REAL,
        total_mined_doom REAL,
        genesis_doom REAL,
        total_l1_doom REAL,
        doom_usd REAL,
        worker_address TEXT,
        status TEXT
    );
CREATE TABLE portfolio_snapshots (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        snapshot_date TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        total_liquid_usd REAL NOT NULL,
        won_pending_usd REAL NOT NULL,
        confirmed_monday_usd REAL NOT NULL,
        active_global_review_usd REAL NOT NULL,
        sprint_review_usd REAL NOT NULL,
        grants_review_usd REAL NOT NULL,
        archived_pipeline_usd REAL NOT NULL,
        grand_total_monitored_usd REAL NOT NULL,
        tracked_bounties_count INTEGER NOT NULL,
        won_prs_count INTEGER NOT NULL,
        active_mining_nodes INTEGER NOT NULL,
        settlement_wallet TEXT NOT NULL,
        audit_summary TEXT
    );
CREATE TABLE transactions_ledger (
        id TEXT PRIMARY KEY,
        date_str TEXT,
        timestamp INTEGER,
        tx_type TEXT,
        type_label TEXT,
        badge_class TEXT,
        concept TEXT,
        rail TEXT,
        account TEXT,
        asset_in TEXT,
        asset_in_usd REAL DEFAULT 0,
        asset_out TEXT,
        asset_out_usd REAL DEFAULT 0,
        net_usd REAL DEFAULT 0,
        fee TEXT,
        tx_hash TEXT,
        explorer_url TEXT,
        status TEXT,
        lifecycle TEXT,
        notes TEXT
    );
CREATE TABLE wallets (
        id TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        address TEXT NOT NULL,
        chain TEXT NOT NULL,
        primary_token TEXT,
        token_balance REAL DEFAULT 0,
        usd_value REAL DEFAULT 0,
        role TEXT,
        notes TEXT,
        last_updated TEXT
    );
CREATE TABLE won_prs (
        id TEXT PRIMARY KEY,
        repo TEXT NOT NULL,
        pr TEXT NOT NULL,
        title TEXT NOT NULL,
        nominal_amount_usd REAL DEFAULT 0,
        audited_amount_usd REAL DEFAULT 0,
        date_merged TEXT,
        url TEXT,
        status TEXT,
        notes TEXT
    );
CREATE INDEX idx_bounties_status ON bounties(status);
CREATE INDEX idx_bounties_repo ON bounties(repo);
CREATE INDEX idx_bounties_is_won ON bounties(is_won);
CREATE INDEX idx_bounties_is_in_review ON bounties(is_in_review);
CREATE INDEX idx_bounties_is_sprint ON bounties(is_sprint);
CREATE INDEX idx_tx_timestamp ON transactions_ledger(timestamp);
DELETE FROM "sqlite_sequence";
COMMIT;
